<?php
namespace App\Livewire;
use App\Models\Exam;use App\Models\ExamPaper;use App\Models\SchoolClass;use App\Models\Stream;use App\Models\Subject;use Illuminate\Support\Facades\Auth;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class ExamSetup extends Component{public string $name='',$classId='',$streamId='',$examId='',$subjectId='',$maximumScore='100',$weighting='1';public function addExam():void{$school=Auth::user()->school;$term=$school->currentTerm();if(!$term||!$term->isOpen()){session()->flash('error','Open a term before creating an exam.');return;}$this->validate(['name'=>'required|string|max:255','classId'=>'required|exists:school_classes,id','streamId'=>'nullable|exists:streams,id']);$exam=Exam::create(['school_id'=>$school->id,'term_id'=>$term->id,'school_class_id'=>$this->classId,'stream_id'=>$this->streamId?:null,'name'=>$this->name,'status'=>'draft']);$this->examId=(string)$exam->id;$this->reset(['name','streamId']);session()->flash('status','Exam created. Add its subject papers below.');}public function addPaper():void{$exam=Exam::where('school_id',Auth::user()->school_id)->findOrFail($this->examId);$this->validate(['subjectId'=>'required|exists:subjects,id','maximumScore'=>'required|numeric|min:1','weighting'=>'required|numeric|min:0.01']);ExamPaper::updateOrCreate(['exam_id'=>$exam->id,'subject_id'=>$this->subjectId],['maximum_score'=>$this->maximumScore,'weighting'=>$this->weighting]);session()->flash('status','Exam paper saved.');}public function render(){$school=Auth::user()->school;return view('livewire.exam-setup',['term'=>$school->currentTerm(),'classes'=>SchoolClass::where('school_id',$school->id)->get(),'streams'=>$this->classId?Stream::where('school_class_id',$this->classId)->get():collect(),'subjects'=>Subject::where('school_id',$school->id)->get(),'exams'=>Exam::with(['schoolClass','papers.subject'])->where('school_id',$school->id)->latest()->get(),'pageTitle'=>'Exam Setup']);}}
